# Checks
# ---------------------------------------------------------------------------


def check_vault_layout(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    home = policy["home_file"]
    maps_dir = policy["maps_dir"]
    if home not in vault.index:
        findings.append(Finding(
            "error", home, 1, "vault_layout",
            "vault has no home note",
            "materialize the vault payload (setup, or the stewardship copy"
            " rule) so navigation has a root"))
    for subtree in policy["subtrees"]:
        if not (vault.root / subtree).is_dir():
            continue
        if not subtree_has_notes(vault, subtree):
            continue  # a map is born with its tree's first note
        map_rel = f"{maps_dir}/{subtree}.md"
        if map_rel not in vault.index:
            findings.append(Finding(
                "error", map_rel, 1, "vault_layout",
                f"subtree '{subtree}' has no map note",
                "seed the map from the vault payload and curate it"))
    for name in policy.get("extra_maps", []):
        map_rel = f"{maps_dir}/{name}.md"
        if map_rel not in vault.index:
            findings.append(Finding(
                "error", map_rel, 1, "vault_layout",
                f"map note '{name}' is missing",
                "seed it from the vault payload"))
    known_roots = set(policy["subtrees"]) | {
        maps_dir, ".obsidian", ".trash",
        policy.get("attachments_dir", "_attachments"),
    }
    known_roots.update(p.rstrip("/").split("/")[0]
                       for p in policy.get("generated_subtrees", []))
    # The vault root holds exactly the home note plus policy-listed
    # root-level generated views. Every other root file is outside layout.
    known_files = {home}
    known_files.update(v for v in policy.get("generated_views", [])
                       if "/" not in v)
    attachments = policy.get("attachments_dir", "_attachments")
    embedded = {t for note in vault.notes.values()
                for (_, embed, t, _, _, _) in note.wikilinks if embed}
    for rel in sorted(vault.index):
        top = rel.split("/")[0]
        if rel.rsplit("/", 1)[-1] == ".gitkeep":
            continue  # git plumbing for empty skeleton directories
        if in_machine_dir(policy, rel):
            continue  # compiler-owned directories manage their own files
        if is_artifact_path(policy, rel):
            if (vault.root / rel).is_symlink():
                findings.append(Finding(
                    "error", rel, 1, "vault_layout",
                    "artifact files must not be symlinks",
                    "copy the artifact into the vault; opaque artifacts may not escape it"))
            continue
        if rel.endswith(".base"):
            findings.append(Finding(
                "error", rel, 1, "vault_layout",
                "base files are not part of the vault contract",
                "views are markdown map notes and generated indexes;"
                " remove the base file"))
            continue
        if top == ".obsidian":
            continue
        if "/" not in rel:
            if rel.endswith(".md"):
                if rel not in known_files and rel not in {home}:
                    findings.append(Finding(
                        "error", rel, 1, "vault_layout",
                        f"root-level note '{rel}' is outside the vault layout",
                        "notes live inside a policy subtree; move it or"
                        " register the surface in vault-policy.json"))
            elif rel not in known_files:
                findings.append(Finding(
                    "error", rel, 1, "vault_layout",
                    f"root-level file '{rel}' is outside the vault layout",
                    "only policy-listed views and the payload live at the"
                    " vault root"))
            continue
        if top not in known_roots:
            findings.append(Finding(
                "error", rel, 1, "vault_layout",
                f"unknown top-level directory '{top}'",
                "vault subtrees are policy-listed; add it to"
                " vault-policy.json or move the content"))
        elif top == attachments:
            if Path(rel).suffix.lower() not in set(
                    policy.get("attachment_extensions", [])):
                findings.append(Finding(
                    "error", rel, 1, "vault_layout",
                    "attachment format is not supported by the vault policy",
                    "convert it to a policy-listed Obsidian-supported binary"
                    " format"))
            elif rel not in embedded:
                findings.append(Finding(
                    "error", rel, 1, "vault_layout",
                    "attachment is not referenced by any embed",
                    "reference it with an embed wikilink or delete it"))
        elif (not rel.endswith(".md")
              and top not in {
                p.rstrip("/").split("/")[0]
                for p in policy.get("generated_subtrees", [])}):
            findings.append(Finding(
                "error", rel, 1, "vault_layout",
                f"non-markdown file '{rel}' inside a note subtree",
                "attachments live under the attachments directory;"
                " transient working files leave the vault before the gate"))


def check_wikilink_resolution(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        for (lineno, embed, target, _anchor, _alias, _inner) in note.wikilinks:
            if not target:
                continue  # pure in-note anchor form is judged by anchor check
            resolved = (target in vault.index if embed
                        else f"{target}.md" in vault.index)
            if not resolved:
                findings.append(Finding(
                    "error", note.rel, lineno, "wikilink_resolution",
                    f"unresolved wikilink target '{target}'",
                    "targets are vault-absolute paths from the vault root"
                    " (no leading slash, forward slashes, exact case)"))


def check_anchor_resolution(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        for (lineno, _embed, target, anchor, _alias, _inner) in note.wikilinks:
            if not anchor:
                continue
            if not anchor.startswith("^"):
                findings.append(Finding(
                    "error", note.rel, lineno, "anchor_resolution",
                    f"heading anchor '#{anchor}' is banned",
                    "link the note itself, or a block id (#^block-id);"
                    " heading text is prose and dies silently"))
                continue
            target_note = vault.notes.get(f"{target}.md" if target else note.rel)
            if target_note and anchor[1:] not in target_note.block_ids:
                findings.append(Finding(
                    "error", note.rel, lineno, "anchor_resolution",
                    f"block anchor '{anchor}' does not exist in"
                    f" '{target or note.rel}'",
                    "add the ^block-id to the target line or fix the anchor"))


def check_link_policy(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        for (lineno, embed, target, _anchor, alias, _inner) in note.wikilinks:
            if target and not embed and not alias:
                findings.append(Finding(
                    "error", note.rel, lineno, "link_policy",
                    f"vault wikilink to '{target}' has no display alias",
                    "every prose and structural note link is vault-absolute"
                    " and aliased; embeds are the only alias-free form"))
        for (lineno, _text, target) in note.mdlinks:
            if target.startswith(("http://", "https://", "mailto:", "#", "/")):
                continue
            clean = target.split("#", 1)[0]
            if not clean:
                continue
            resolved = (note.path.parent / clean).resolve()
            try:
                resolved.relative_to(vault.root)
                inside = True
            except ValueError:
                inside = False
            artifact_link = (inside and resolved.is_file()
                             and is_artifact_path(
                                 vault.policy, rel_posix(vault.root, resolved)))
            if inside and not artifact_link:
                findings.append(Finding(
                    "error", note.rel, lineno, "link_policy",
                    f"vault-internal citation uses a markdown link: {target}",
                    "cite vault content as a vault-absolute wikilink with an"
                    " alias; the normalize verb rewrites this class"))
            elif not resolved.exists():
                findings.append(Finding(
                    "warning", note.rel, lineno, "link_policy",
                    f"out-of-vault link target does not exist: {target}",
                    "fix the relative path or drop the link"))


def check_table_pipe(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        in_fence = False
        for lineno, line in enumerate(note.lines, start=1):
            if lineno < note.fm_end:
                continue
            if line.lstrip().startswith("```"):
                in_fence = not in_fence
                continue
            if in_fence or not is_table_row(line):
                continue
            for match in WIKILINK_RE.finditer(INLINE_CODE_RE.sub("", line)):
                inner = match.group("inner")
                if re.search(r"(?<!\\)\|", inner):
                    findings.append(Finding(
                        "error", note.rel, lineno, "table_pipe",
                        "unescaped alias pipe inside a table-cell wikilink",
                        "escape it as \\| or the pipe splits the row"))


def is_separator_row(line: str) -> bool:
    stripped = line.strip()
    return (stripped.startswith("|") and "-" in stripped
            and set(stripped.replace("|", "").strip()) <= set("-: "))


def check_table_shape(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        in_fence = False
        prev_is_row = False
        for lineno, line in enumerate(note.lines, start=1):
            if lineno < note.fm_end:
                continue
            if line.lstrip().startswith("```"):
                in_fence = not in_fence
                prev_is_row = False
                continue
            if in_fence:
                continue
            row_here = is_table_row(line)
            if row_here and not prev_is_row:
                nxt = note.lines[lineno] if lineno < len(note.lines) else ""
                if not is_separator_row(nxt):
                    findings.append(Finding(
                        "error", note.rel, lineno, "table_shape",
                        "table header row is not followed by its separator"
                        " row",
                        "put the |---| separator directly under the header;"
                        " a fenced block right after the header swallows the"
                        " whole table into plain text"))
            prev_is_row = row_here


def check_banned_basename(vault: Vault, findings: list[Finding]) -> None:
    """Policy-banned generic basenames only. Duplicate basenames across
    folders are legal: the title layer owns display identity (title
    uniqueness is title_shape's warning). Findings are per FILE (never
    vault-global) so scoped gates compose."""
    policy = vault.policy
    banned = set(policy.get("banned_basenames", []))
    for note in authored(vault):
        if in_machine_dir(policy, note.rel):
            continue
        name = note.rel.rsplit("/", 1)[-1]
        if name in banned:
            findings.append(Finding(
                "error", note.rel, 1, "banned_basename",
                f"basename '{name}' is policy-banned",
                "generic filenames say nothing; give the file a meaningful"
                " slug name (typed content: <slug>-<document-kind>.md)"))


def note_decision_tree(policy: dict, rel: str) -> dict | None:
    for tree in policy.get("decision_trees", {}).values():
        path = tree["path"].rstrip("/")
        if "*" in path:
            if "/" in rel and glob_match(path, rel.rsplit("/", 1)[0]):
                return tree
        elif rel.startswith(path + "/"):
            return tree
    return None


# The shape of a record id a note may own through its aliases: PREFIX-,
# an optional node code, then digits (SD-001, ADR-012, DEC-INV-001).
ID_ALIAS_RE = re.compile(r"^[A-Z][A-Z0-9]*(?:-[A-Z0-9]{2,4})?-\d{3,}$")


def id_shaped_aliases(note: Note) -> list[str]:
    aliases = note.fm.get("aliases")
    if not isinstance(aliases, list):
        return []
    return [str(a).strip() for a in aliases
            if isinstance(a, str) and ID_ALIAS_RE.fullmatch(str(a).strip())]


def check_title_shape(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    banned_stems = {b[:-3] for b in policy.get("banned_basenames", [])}
    seen_titles: dict[str, str] = {}
    for note in authored(vault):
        if in_machine_dir(policy, note.rel):
            continue
        title = note.fm.get("title")
        if not isinstance(title, str) or not title.strip():
            findings.append(Finding(
                "error", note.rel, 1, "title_shape",
                "authored note has no title",
                "the title is the user-facing graph label: a natural"
                " output_language phrase that names the content, never"
                " id-led"))
            continue
        for alias in id_shaped_aliases(note):
            if title.startswith(alias):
                findings.append(Finding(
                    "error", note.rel, 1, "title_shape",
                    f"title is id-led ('{alias}')",
                    "ids live in the frontmatter alias, never in the"
                    " label; the normalize verb strips this class"))
                break
        first_h1 = next((text for (_l, text, level) in note.headings
                         if level == 1), None)
        if first_h1 is not None and first_h1 != title:
            findings.append(Finding(
                "error", note.rel, 1, "title_shape",
                f"first H1 '{first_h1}' is not byte-identical to the title",
                "the H1 and the title are one label; edit them in the"
                " same write"))
        stem = note.rel.rsplit("/", 1)[-1][:-3]
        if title == stem:
            findings.append(Finding(
                "error", note.rel, 1, "title_shape",
                "title is byte-identical to the basename stem",
                "titles are human-readable output_language labels; a"
                " humanized form of the slug is compliant, the raw stem"
                " is not"))
        if title.strip().lower() in banned_stems:
            findings.append(Finding(
                "error", note.rel, 1, "title_shape",
                f"generic title '{title}'",
                "a generic label is meaningless in the graph; qualify it"
                " with its owning space or subject"))
        title_key = title.casefold()
        if title_key in seen_titles:
            findings.append(Finding(
                "error", note.rel, 1, "title_shape",
                f"title '{title}' is also used by {seen_titles[title_key]}",
                "duplicate labels are indistinguishable in the graph;"
                " qualify one of them"))
        else:
            seen_titles[title_key] = note.rel


def check_map_coverage(vault: Vault, findings: list[Finding]) -> None:
    """Every policy-hub note is linked from its subtree map. Leaves stay
    optional on maps; hubs are the map's contract."""
    policy = vault.policy
    maps_dir = policy["maps_dir"]
    for rel in sorted(vault.notes):
        note = vault.notes[rel]
        if note.generated or not is_map_hub(policy, rel):
            continue
        map_rel = f"{maps_dir}/{rel.split('/')[0]}.md"
        map_note = vault.notes.get(map_rel)
        if map_note is None:
            continue  # vault_layout reports the missing map
        targets = {t for (_, _, t, _, _, _) in map_note.wikilinks}
        if rel[:-3] not in targets:
            findings.append(Finding(
                "error", map_rel, 1, "map_coverage",
                f"map does not link the hub '{rel[:-3]}'",
                "every policy hub gets an inbound link from its subtree"
                " map; leaves are optional, hubs are not"))


def check_alias_ownership(vault: Vault, findings: list[Finding]) -> None:
    """An id-shaped link alias must decorate a link to the id's owning
    note: decision-tree ids resolve by frontmatter alias, BA row ids through the
    target space's generated registry. Absent or unknown = silent skip."""
    policy = vault.policy
    owners: dict[str, str] = {}
    for tree in policy.get("decision_trees", {}).values():
        for note in decision_notes(vault, tree):
            rec_id = decision_id(tree, note)
            if rec_id is not None:
                owners.setdefault(rec_id, note.rel)
    registries: dict[str, dict | None] = {}

    def space_registry(rel: str) -> tuple[str, dict] | None:
        parts = rel.split("/")
        for i in range(1, len(parts)):
            root = "/".join(parts[:i])
            reg_rel = f"{root}/_generated/registry.json"
            if reg_rel not in vault.index:
                continue
            if root not in registries:
                try:
                    registries[root] = json.loads(
                        (vault.root / reg_rel).read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError):
                    registries[root] = None
            data = registries[root]
            return (root, data) if isinstance(data, dict) else None
        return None

    for note in authored(vault):
        for (lineno, embed, target, _anchor, alias, _inner) in note.wikilinks:
            if embed or not target or not alias:
                continue
            aid = alias.strip()
            owner = owners.get(aid)
            if owner is not None:
                if f"{target}.md" != owner:
                    findings.append(Finding(
                        "error", note.rel, lineno, "alias_ownership",
                        f"alias '{aid}' decorates a link to '{target}' but"
                        f" the id's owning note is {owner}",
                        "an id-shaped alias always rides a link to its"
                        " owner; use plain prose for anything else"))
                continue
            if not NAMESPACED_ID_RE.fullmatch(aid):
                continue
            resolved = space_registry(f"{target}.md")
            if resolved is None:
                continue  # no registry in reach: silent skip
            root, registry = resolved
            info = registry.get("ids", {}).get(aid)
            if not isinstance(info, dict) or "doc" not in info:
                continue  # unknown id: silent skip
            owner_rel = f"{root}/{info['doc']}"
            if f"{target}.md" != owner_rel:
                findings.append(Finding(
                    "error", note.rel, lineno, "alias_ownership",
                    f"alias '{aid}' decorates a link to '{target}' but the"
                    f" registry declares its owner as {owner_rel}",
                    "an id-shaped alias always rides a link to its owner;"
                    " re-render the space if the registry is stale"))


def check_orphans(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    home = policy["home_file"]
    for note in authored(vault):
        if note.rel == home:
            continue  # the navigation root is exempt by definition
        if not vault.inbound.get(note.rel):
            findings.append(Finding(
                "error", note.rel, 1, "orphans",
                "note has no inbound wikilink",
                "link it from its map note or owning hub; every note is"
                " part of the graph or it does not exist"))


def check_moc_coverage(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    home = policy["home_file"]
    if home not in vault.notes:
        return  # vault_layout already reports the missing root
    reachable: set[str] = set()
    frontier = [home]
    while frontier:
        rel = frontier.pop()
        if rel in reachable:
            continue
        reachable.add(rel)
        note = vault.notes.get(rel)
        if note is None:
            continue
        targets = [t for (_, _, t, _, _, _) in note.wikilinks if t]
        targets.extend(t for (_, t) in note.fm_targets if t)
        for target in targets:
            frontier.append(f"{target}.md")
    for note in authored(vault):
        if note.rel not in reachable:
            findings.append(Finding(
                "error", note.rel, 1, "moc_coverage",
                "note is not reachable from the home note",
                "add it to its subtree map (directly or through a hub the"
                " map links)"))


def check_nav_footer(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    maps_dir = policy["maps_dir"]
    exempt = {policy["home_file"]}
    for note in authored(vault):
        if note.rel in exempt or note.subtree == maps_dir or not note.subtree:
            continue
        nav_line = next((i for i, line in enumerate(note.lines, start=1)
                         if NAV_MARKER in line), None)
        if nav_line is None:
            findings.append(Finding(
                "error", note.rel, max(len(note.lines), 1), "nav_footer",
                f"note has no nav section ({NAV_MARKER})",
                "end every leaf with the nav section: first wikilink is the"
                " owning map, then the contextual peers"))
            continue
        links = [(lineno, target)
                 for (lineno, embed, target, _a, _al, _inner) in note.wikilinks
                 if lineno >= nav_line and target and not embed]
        owning_map = f"{maps_dir}/{note.subtree}"
        if is_hub(policy, note.rel):
            expected = owning_map
        else:
            hub = resolve_hub(policy, vault.index, note.rel)
            expected = hub[:-3] if hub else owning_map
        if not links or links[0][1] != expected:
            findings.append(Finding(
                "error", note.rel, nav_line, "nav_footer",
                f"nav section's first wikilink must be the owning hub"
                f" '{expected}'",
                "the up-edge is positional: the policy hub ladder's owner"
                " first (hubs and uncovered notes keep the subtree map),"
                " peers after"))
            continue


def property_type_ok(value, expected: str) -> bool:
    if expected in {"list", "multitext", "tags", "aliases"}:
        return isinstance(value, list)
    if expected == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if expected == "checkbox":
        return isinstance(value, bool)
    if expected in ("date", "datetime"):
        return isinstance(value, str) and bool(DATE_RE.match(value[:10]))
    return isinstance(value, str)


def check_frontmatter_props(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    prop_types = policy.get("property_types", {})
    known_types = known_doc_types(policy)
    path_patterns = policy.get("type_path_patterns", {})
    status_values = policy.get("status_values", {})
    relation_contract = policy.get("relation_contract", {})
    required_relations = relation_contract.get("required_by_type_status", {}) \
        if isinstance(relation_contract, dict) else {}
    cardinalities = relation_contract.get("cardinality_by_type", {}) \
        if isinstance(relation_contract, dict) else {}
    for note in authored(vault):
        if note.fm_error:
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"frontmatter: {note.fm_error}",
                "every authored note opens with a frontmatter block"))
            continue
        for key in ("type",):
            if not note.fm.get(key):
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"frontmatter floor: '{key}' is missing",
                    "every authored note declares its type"))
        raw_type = str(note.fm.get("type", ""))
        note_type = kebab(raw_type) if raw_type else ""
        if note_type and note_type not in known_types:
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"unknown document type '{raw_type}'",
                "the vault taxonomy is closed; register the type, path,"
                " properties, status and graph group before using it"))
        schema_type = note_type.replace("-", "_")
        patterns = path_patterns.get(schema_type, []) \
            if isinstance(path_patterns, dict) else []
        if patterns and not any(re.fullmatch(pattern, note.rel)
                                for pattern in patterns):
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"type '{note_type}' is not legal at this path",
                "move the note to one of its policy-declared path grammars"))
        status = note.fm.get("status")
        allowed_status = status_values.get(schema_type) \
            if isinstance(status_values, dict) else None
        if status is not None and isinstance(allowed_status, list) \
                and status not in allowed_status:
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"status '{status}' is not legal for type '{note_type}'",
                "use the type's policy-declared lifecycle value"))
        for key in sorted(set(note.fm) - set(prop_types)):
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"unknown frontmatter property '{key}'",
                "the vault property schema is closed; register the property"
                " and its one vault-wide Obsidian type before using it"))
        requirements = required_relations.get(schema_type, {}) \
            if isinstance(required_relations, dict) else {}
        if isinstance(requirements, dict):
            required = list(requirements.get("all_statuses", []))
            required.extend(requirements.get(str(status), []))
            for key in sorted(set(required)):
                value = note.fm.get(key)
                if not isinstance(value, list) or not value:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"type '{note_type}' requires relation '{key}'",
                        "declare the typed cross-subtree relation as a"
                        " quoted wikilink block list"))
        type_cardinality = cardinalities.get(schema_type, {}) \
            if isinstance(cardinalities, dict) else {}
        if isinstance(type_cardinality, dict):
            for key, limits in sorted(type_cardinality.items()):
                values = note.fm.get(key, [])
                count = len(values) if isinstance(values, list) else 0
                minimum = int(limits.get("min", 0))
                maximum = int(limits.get("max", 2 ** 31 - 1))
                if not minimum <= count <= maximum:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' cardinality is {count}; expected"
                        f" {minimum}-{maximum}",
                        "use the source type's closed relation cardinality"))
        for key in ("tag", "alias", "cssclass"):
            if key in note.fm:
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"singular '{key}:' key is dead vault grammar",
                    f"use the list key '{key}s' (dash items, one per line)"))
        for key in ("tags", "aliases"):
            if key not in note.fm:
                continue
            value = note.fm[key]
            if isinstance(value, str):
                shape = ("inline flow list" if FLOW_LIST_RE.match(value)
                         else "scalar")
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"'{key}' is a {shape}; the contract is a block list",
                    f"write '{key}:' then one '- item' line per value"))
        if "tags" not in note.fm:
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                "frontmatter floor: 'tags' is missing",
                "every authored note carries its tag mirror"))
        for key, expected in sorted(prop_types.items()):
            if key in note.fm and not property_type_ok(note.fm[key], expected):
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"'{key}' does not match its vault-wide property type"
                    f" '{expected}'",
                    "one value type per key, vault-wide; dates are"
                    " YYYY-MM-DD"))
        for key, target in note.fm_targets:
            if target and f"{target}.md" not in vault.index:
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"frontmatter link '{key}' targets missing note"
                    f" '{target}'",
                    "frontmatter links are vault-absolute wikilinks to"
                    " existing notes"))
        for lineno in range(1, note.fm_end - 1):
            if lineno - 1 >= len(note.lines):
                break
            raw = note.lines[lineno - 1]
            if re.match(r"^\s*(?:- )?(?:[a-z0-9_]+:)?\s*\[\[", raw):
                findings.append(Finding(
                    "error", note.rel, lineno, "frontmatter_props",
                    "unquoted wikilink in frontmatter",
                    "quote wikilink values (\"[[...]]\") or the frontmatter"
                    " is not valid YAML to the vault app"))
    check_relation_contract(vault, findings)


def canonical_scope_for_note(note: Note) -> str | None:
    parts = note.rel.split("/")
    if len(parts) < 3 or parts[0] != "business-analysis":
        return None
    space = parts[1]
    if note.rel == f"business-analysis/{space}/space.md":
        return space
    if note.rel.endswith("/domain.md") and "domains" in parts:
        tail = parts[2:-1]
        domains: list[str] = []
        for index, value in enumerate(tail):
            if value == "domains" and index + 1 < len(tail):
                domains.append(tail[index + 1])
        if domains:
            return space + "#domains/" + "/domains/".join(domains)
    return None


def relation_identity_owners(vault: Vault) -> dict[str, str]:
    owners: dict[str, str] = {}
    for note in authored(vault):
        aliases = note.fm.get("aliases")
        if isinstance(aliases, list):
            for alias in aliases:
                if isinstance(alias, str):
                    owners.setdefault(alias.strip(), note.rel)
        scope = canonical_scope_for_note(note)
        if scope:
            owners.setdefault(scope, note.rel)
        ident = note.fm.get("id")
        revision = note.fm.get("revision")
        if isinstance(ident, str) and isinstance(revision, int):
            match = re.match(r"experience-design/experiences/([a-z0-9]+(?:-[a-z0-9]+)*)/", note.rel)
            if match:
                owners.setdefault(f"{match.group(1)}:{ident}@r{revision}", note.rel)
        architecture_id = note.fm.get("record_id")
        component = note.fm.get("component_ref")
        if isinstance(architecture_id, str) and isinstance(revision, int):
            if architecture_id.startswith("CON-"):
                owners.setdefault(f"ARC:{architecture_id}@r{revision}", note.rel)
            elif isinstance(component, str) and component:
                owners.setdefault(f"ARC:{component}:{architecture_id}@r{revision}", note.rel)
        if kebab(str(note.fm.get("type", ""))) == "solution-component":
            component_id = note.fm.get("component_id")
            if isinstance(component_id, str) and component_id:
                owners.setdefault(f"solution-component:{component_id}", note.rel)
        if note.rel == "solution-design/landscape.md":
            owners.setdefault("solution-design/landscape", note.rel)
        if note.rel == "design-system/MASTER.md":
            owners.setdefault("design-system/MASTER", note.rel)
    ba_root = vault.root / "business-analysis"
    if ba_root.is_dir():
        for registry_path in sorted(ba_root.glob("*/_generated/registry.json")):
            try:
                registry = json.loads(registry_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            space = registry_path.parents[1].name
            for ident, info in (registry.get("ids") or {}).items():
                if isinstance(info, dict) and isinstance(info.get("doc"), str):
                    rel = f"business-analysis/{space}/{info['doc']}"
                    owners.setdefault(f"{space}:{ident}", rel)
                    owners.setdefault(str(ident), rel)
    return owners


def relation_edges(vault: Vault) -> list[RelationEdge]:
    edges: list[RelationEdge] = []
    keys = relation_specs(vault.policy)
    for note in authored(vault):
        for key in sorted(keys):
            values = note.fm.get(key)
            if not isinstance(values, list):
                continue
            for value in values:
                if isinstance(value, str) and value.startswith("[[") and value.endswith("]]" ):
                    target, _anchor, alias = split_wikilink(value[2:-2])
                    target_rel = f"{target}.md"
                elif isinstance(value, str):
                    target_rel = relation_identity_owners(vault).get(value, "")
                    alias = value
                else:
                    continue
                if target_rel and alias and target_rel in vault.notes:
                    edges.append(RelationEdge(
                        note.rel, target_rel, key, alias.strip()))
    return sorted(edges, key=lambda item: (
        item.target, item.key, item.source, item.alias))


def check_relation_contract(vault: Vault, findings: list[Finding]) -> None:
    specs = relation_specs(vault.policy)
    owners = relation_identity_owners(vault)
    for note in authored(vault):
        for key, spec in sorted(specs.items()):
            if key not in note.fm:
                continue
            values = note.fm.get(key)
            if not isinstance(values, list) or not values:
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"relation '{key}' must be a non-empty block list",
                    "write one quoted aliased vault-absolute wikilink per"
                    " list item"))
                continue
            for value in values:
                semantic_types = {"experience", "journey", "flow-set", "screen", "state", "transition", "architecture-component", "architecture-module", "interface-contract", "data-model", "threat-model", "runtime-view", "reliability-view", "observability-view", "architecture-connection"}
                note_type = kebab(str(note.fm.get("type", "")))
                if (isinstance(value, str) and note_type in semantic_types
                        and value in owners):
                    target_rel = owners[value]
                    target_note = vault.notes.get(target_rel)
                    target = target_rel.removesuffix(".md")
                    alias = value
                elif not (isinstance(value, str) and value.startswith("[[")
                          and value.endswith("]]")):
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' contains a non-wikilink value",
                        "typed relations contain only quoted vault-absolute"
                        " wikilinks"))
                    continue
                else:
                    target, _anchor, alias = split_wikilink(value[2:-2])
                    target_rel = f"{target}.md" if target else ""
                    target_note = vault.notes.get(target_rel)
                if not target or target_note is None or target_note.generated:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' targets missing or generated note"
                        f" '{target}'",
                        "target the canonical authored note, never a registry"
                        " or generated view"))
                    continue
                if target_rel == note.rel:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' points to its own note",
                        "drop the self edge or target the distinct knowledge"
                        " record"))
                if not alias:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' to '{target}' has no alias",
                        "the alias carries the canonical id or readable"
                        " relation label"))
                targets = spec.get("targets", []) if isinstance(spec, dict) else []
                target_type = kebab(str(target_note.fm.get("type", "")))
                if "*" not in targets and target_type not in targets:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' cannot target type '{target_type}'",
                        "use a target type allowed by the relation matrix"))
                if alias and alias in owners and owners[alias] != target_rel:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation alias '{alias}' belongs to"
                        f" '{owners[alias]}', not '{target_rel}'",
                        "an exact scope, criterion or stable id aliases only"
                        " its owning note"))
                target_identities = {
                    identity for identity, owner in owners.items()
                    if owner == target_rel and (
                        re.fullmatch(r"(?:SD|ADR)-[0-9]{3,}", identity)
                        or re.fullmatch(
                            r"[a-z0-9]+(?:-[a-z0-9]+)*:(?:JRN|FLW|SCR|STA|TRN)-"
                            r"[0-9]{3,}@r[1-9][0-9]*", identity
                        ) or re.fullmatch(
                            r"ARC:(?:[a-z0-9]+(?:-[a-z0-9]+)*:)?(?:MOD|IFC|DAT|THR|RUN|REL|OBS|CON)-[0-9]{3,}@r[1-9][0-9]*",
                            identity))
                }
                if target_identities and alias not in target_identities:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation alias '{alias}' is not the target's exact"
                        " canonical identity",
                        "use one of: " + ", ".join(sorted(target_identities))))
                if key == "satisfies" and alias and alias not in owners:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"satisfies alias '{alias}' is not a qualified BA id",
                        "use <space>:<criterion-id> on the criterion's owning"
                        " BA note"))
                elif key == "satisfies" and alias and not re.fullmatch(
                        r"[a-z0-9]+(?:-[a-z0-9]+)*:"
                        r"(?:AC|BR|BUD)-[A-Z0-9-]+-[0-9]{3,}", alias):
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"satisfies alias '{alias}' is not qualified",
                        "use <space>:<criterion-id> exactly"))
                if key == "derives_from" and target_type in {"space", "domain"}:
                    expected = canonical_scope_for_note(target_note)
                    if expected and alias != expected:
                        findings.append(Finding(
                            "error", note.rel, 1, "frontmatter_props",
                            f"analysis scope alias '{alias}' must be"
                            f" '{expected}'",
                            "the relation alias is the canonical BA scope"))


def relation_source_alias(note: Note) -> str:
    aliases = note.fm.get("aliases")
    if isinstance(aliases, list):
        for alias in aliases:
            if isinstance(alias, str) and re.fullmatch(
                    r"(?:SD|ADR)-[0-9]{3,}|DEC-[A-Z]{2,4}-[0-9]{3,}", alias):
                return alias
    ident = note.fm.get("id")
    revision = note.fm.get("revision")
    if isinstance(ident, str) and isinstance(revision, int):
        match = re.match(r"experience-design/experiences/([a-z0-9]+(?:-[a-z0-9]+)*)/", note.rel)
        if match:
            return f"{match.group(1)}:{ident}@r{revision}"
    record_id = note.fm.get("record_id")
    component = note.fm.get("component_ref")
    if isinstance(record_id, str) and isinstance(revision, int):
        if record_id.startswith("CON-"):
            return f"ARC:{record_id}@r{revision}"
        if isinstance(component, str) and component:
            return f"ARC:{component}:{record_id}@r{revision}"
    title = note.fm.get("title")
    if isinstance(title, str) and title:
        return title
    h1 = next((text for _line, text, level in note.headings if level == 1), "")
    return h1 or note.path.stem


def relation_projection(vault: Vault) -> tuple[dict[str, str], dict[str, str]]:
    contract = vault.policy.get("relation_contract", {})
    inline_max = int(contract.get("inverse_inline_max", 100))
    page_size = int(contract.get("catalog_page_size", 100))
    catalog_root = str(contract.get("catalog_root", "maps/_relations")).rstrip("/")
    specs = relation_specs(vault.policy)
    grouped: dict[str, list[RelationEdge]] = {}
    for edge in relation_edges(vault):
        grouped.setdefault(edge.target, []).append(edge)
    blocks: dict[str, str] = {}
    catalogs: dict[str, str] = {}
    for target, edges in sorted(grouped.items()):
        rows: list[str] = []
        if len(edges) <= inline_max:
            for edge in edges:
                source = vault.notes[edge.source]
                label = str(specs[edge.key]["inverse_label"])
                rows.append(
                    f"- {label}: [[{edge.source[:-3]}|{relation_source_alias(source)}]]")
        else:
            key = hashlib.sha256(target.encode()).hexdigest()[:12]
            pages = [edges[index:index + page_size]
                     for index in range(0, len(edges), page_size)]
            for number, page in enumerate(pages, start=1):
                rel = f"{catalog_root}/{key}/relations-{number:03d}.md"
                rows.append(
                    f"- Related knowledge {number:03d}: [[{rel[:-3]}|catalog {number:03d}]]")
                target_note = vault.notes[target]
                lines = [RELATION_CATALOG_MARKER,
                         f"# Related knowledge {number:03d}", "",
                         f"Target: [[{target[:-3]}|{target_note.fm.get('title', target_note.path.stem)}]]",
                         ""]
                for edge in page:
                    source = vault.notes[edge.source]
                    label = str(specs[edge.key]["inverse_label"])
                    lines.append(
                        f"- {label}: [[{edge.source[:-3]}|{relation_source_alias(source)}]]")
                catalogs[rel] = "\n".join(lines) + "\n"
        blocks[target] = (RELATION_START + "\n\n" + "\n".join(rows)
                          + "\n\n" + RELATION_END)
    return blocks, catalogs


def relation_reports(vault: Vault) -> dict[str, str]:
    edges = relation_edges(vault)
    rows = [RELATION_CATALOG_MARKER, "# Cross-subtree matrix", "",
            "| Source | Relation | Target | Canonical ref |",
            "|---|---|---|---|"]
    for edge in edges:
        source = relation_source_alias(vault.notes[edge.source])
        target = relation_source_alias(vault.notes[edge.target])
        rows.append(
            f"| [[{edge.source[:-3]}\\|{source}]] | `{edge.key}` | "
            f"[[{edge.target[:-3]}\\|{target}]] | `{edge.alias}` |")
    if not edges:
        rows.append("| - | - | - | - |")
    owners = relation_identity_owners(vault)
    incoming = {edge.alias for edge in edges}
    qualified = sorted(alias for alias in owners if re.fullmatch(
        r"[a-z0-9-]+:[A-Z]{2,4}-[A-Z0-9]+-[0-9]{3,}", alias))
    missing = [alias for alias in qualified if alias not in incoming]
    uncovered = [RELATION_CATALOG_MARKER, "# Uncovered analysis", ""]
    uncovered.extend(f"- [[{owners[alias][:-3]}|{alias}]]" for alias in missing)
    if not missing:
        uncovered.append("No uncovered qualified analysis references.")
    stale = [RELATION_CATALOG_MARKER, "# Stale relations", "",
             "No stale typed relations. The renderer runs only after relation validation."]
    status = [RELATION_CATALOG_MARKER, "# Relation status", "",
              f"- Typed outgoing relations: {len(edges)}",
              f"- Relation targets: {len({edge.target for edge in edges})}",
              f"- Uncovered qualified analysis refs: {len(missing)}", ""]
    return {
        "maps/_generated/cross-subtree-matrix.md": "\n".join(rows) + "\n",
        "maps/_generated/uncovered-analysis.md": "\n".join(uncovered) + "\n",
        "maps/_generated/stale-relations.md": "\n".join(stale) + "\n",
        "maps/_generated/relation-status.md": "\n".join(status),
    }


def relation_block(text: str) -> str:
    pattern = re.compile(
        re.escape(RELATION_START) + r".*?" + re.escape(RELATION_END),
        re.DOTALL,
    )
    match = pattern.search(text)
    return match.group(0) if match else ""


def replace_relation_block(text: str, block: str) -> str:
    pattern = re.compile(
        r"\n*" + re.escape(RELATION_START) + r".*?"
        + re.escape(RELATION_END) + r"\n*", re.DOTALL,
    )
    cleaned = pattern.sub("\n\n", text).rstrip() + "\n"
    if not block:
        return cleaned
    nav = cleaned.find(NAV_MARKER)
    if nav >= 0:
        heading = cleaned.rfind("\n", 0, nav)
        insertion = heading + 1 if heading >= 0 else nav
        return (cleaned[:insertion].rstrip() + "\n\n" + block + "\n\n"
                + cleaned[insertion:].lstrip())
    return cleaned.rstrip() + "\n\n" + block + "\n"


def check_relation_projections(vault: Vault,
                               findings: list[Finding]) -> None:
    expected_blocks, expected_catalogs = relation_projection(vault)
    for note in authored(vault):
        expected = expected_blocks.get(note.rel, "")
        actual = relation_block(note.path.read_text(encoding="utf-8"))
        if actual != expected:
            findings.append(Finding(
                "error", note.rel, 1, "generated_views",
                "inverse relation projection is stale",
                "run vault_check.py render-relations; approved semantic"
                " content is not changed"))
    catalog_root = str(vault.policy.get("relation_contract", {}).get(
        "catalog_root", "maps/_relations")).rstrip("/")
    actual_catalogs = {
        rel for rel in vault.index
        if rel.startswith(catalog_root + "/") and rel.endswith(".md")
    }
    for rel in sorted(actual_catalogs | set(expected_catalogs)):
        actual = ""
        path = vault.root / rel
        if path.is_file():
            actual = path.read_text(encoding="utf-8")
        if actual != expected_catalogs.get(rel, ""):
            findings.append(Finding(
                "error", rel, 1, "generated_views",
                "inverse relation catalog is stale",
                "run vault_check.py render-relations; catalogs are"
                " compiler-owned and bounded to the policy page size"))
    for rel, expected in relation_reports(vault).items():
        path = vault.root / rel
        actual = path.read_text(encoding="utf-8") if path.is_file() else ""
        if actual != expected:
            findings.append(Finding(
                "error", rel, 1, "generated_views",
                "cross-subtree relation report is stale",
                "run vault_check.py render-relations"))


def kebab(value: str) -> str:
    return str(value).replace("_", "-").lower()


def check_tags_mirror(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        tags = note.fm.get("tags")
        note_type = note.fm.get("type")
        if not isinstance(tags, list) or not note_type:
            continue  # the frontmatter floor already reports the shape
        expected = {f"doc/{kebab(note_type)}"}
        status = note.fm.get("status")
        if status:
            expected.add(f"status/{kebab(status)}")
        if set(tags) != expected:
            findings.append(Finding(
                "error", note.rel, 1, "tags_mirror",
                f"tags {sorted(tags)} must be exactly {sorted(expected)}",
                "tags are the script-stamped mirror of type and status;"
                " never hand-pick tags"))


def tree_is_glob(tree: dict) -> bool:
    return "*" in tree["path"]


def decision_notes(vault: Vault, tree: dict) -> list[Note]:
    ordered = sorted(vault.notes.values(), key=lambda n: n.rel)
    if tree_is_glob(tree):
        pattern = tree["path"].rstrip("/")
        return [n for n in ordered
                if not n.generated and "/" in n.rel
                and glob_match(pattern, n.rel.rsplit("/", 1)[0])]
    prefix = tree["path"].rstrip("/") + "/"
    return [n for n in ordered
            if n.rel.startswith(prefix) and not n.generated]


def tree_id_re(tree: dict) -> re.Pattern:
    """The id grammar a tree's records own: glob (per-space) trees carry
    a node code between prefix and number; flat trees do not."""
    width = tree.get("id_min_width", 3)
    if tree_is_glob(tree):
        return re.compile(rf"^{tree['id_prefix']}-[A-Z]{{2,4}}-\d{{{width},}}$")
    return re.compile(rf"^{tree['id_prefix']}-\d{{{width},}}$")


def tree_id_aliases(tree: dict, note: Note) -> list[str]:
    """Frontmatter aliases matching the tree's id grammar. Non-id
    aliases in the list are tolerated (they are search sugar)."""
    aliases = note.fm.get("aliases")
    if not isinstance(aliases, list):
        return []
    pattern = tree_id_re(tree)
    return [str(a).strip() for a in aliases
            if isinstance(a, str) and pattern.fullmatch(str(a).strip())]


def decision_id(tree: dict, note: Note) -> str | None:
    """The single id-shaped frontmatter alias owned by a decision note."""
    ids = tree_id_aliases(tree, note)
    return ids[0] if len(ids) == 1 else None


def check_decision_records(vault: Vault, findings: list[Finding]) -> None:
    for tree_name, tree in sorted(vault.policy.get("decision_trees", {}).items()):
        seen: dict[str, str] = {}
        notes = decision_notes(vault, tree)
        for note in notes:
            stem = note.rel.rsplit("/", 1)[-1][:-3]
            if not (stem.endswith("-decision")
                    and len(stem) > len("-decision")):
                findings.append(Finding(
                    "error", note.rel, 1, "decision_records",
                    "filename does not match the decision note grammar",
                    "decision notes are <slug>-decision.md; the id lives"
                    " in the frontmatter alias, never in the filename"))
            ids = tree_id_aliases(tree, note)
            if len(ids) != 1:
                findings.append(Finding(
                    "error", note.rel, 1, "decision_records",
                    f"note carries {len(ids)} {tree['id_prefix']}-shaped"
                    " aliases, expected exactly one",
                    "the frontmatter alias is the id's single home;"
                    " mint exactly one id alias per record"))
                continue
            rec_id = decision_id(tree, note)
            if rec_id is None:
                findings.append(Finding(
                    "error", note.rel, 1, "decision_records",
                    f"note owns no {tree['id_prefix']} record id",
                    "mint exactly one matching id in frontmatter aliases"))
                continue
            if rec_id in seen:
                findings.append(Finding(
                    "error", note.rel, 1, "decision_records",
                    f"decision id {rec_id} already minted by {seen[rec_id]}",
                    "ids are unique per tree; renumber the younger note and"
                    " rewrite its referrers in the same commit"))
            else:
                seen[rec_id] = note.rel
            if tree_is_glob(tree):
                # The BA supersede lifecycle belongs to ba_compile (the
                # schema has superseded_by and no supersedes), so the
                # supersede shape and symmetry sub-rules stay scoped to
                # non-glob trees.
                continue
            for key_name in ("supersedes", "superseded_by"):
                target = dict(note.fm_targets).get(key_name, "")
                raw = note.fm.get(key_name, "")
                if raw and not target:
                    findings.append(Finding(
                        "error", note.rel, 1, "decision_records",
                        f"'{key_name}' must be a quoted wikilink or empty",
                        "the supersede chain is a pair of frontmatter"
                        " wikilinks"))
            fm_map = dict(note.fm_targets)
            other_rel = (f"{fm_map['superseded_by']}.md"
                         if "superseded_by" in fm_map else None)
            if other_rel:
                other = vault.notes.get(other_rel)
                back = dict(other.fm_targets).get("supersedes", "") if other else ""
                if not other or f"{back}.md" != note.rel:
                    findings.append(Finding(
                        "error", note.rel, 1, "decision_records",
                        "supersede chain is not symmetric",
                        "stamp-decision writes both ends in one operation;"
                        " never hand-edit the chain"))
        if not tree.get("render_index", True):
            continue  # no generated index for this tree
        index_rel = index_path_for(tree)
        expected = render_decision_index(vault, tree)
        actual_path = vault.root / index_rel
        actual = (actual_path.read_text(encoding="utf-8", errors="replace")
                  if actual_path.is_file() else "")
        if notes and actual != expected:
            findings.append(Finding(
                "error", index_rel, 1, "decision_records",
                f"decision index is stale for tree '{tree_name}'",
                "run the render-decisions verb; the index is generated,"
                " never merged by hand"))


def check_generated_views(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    marker_prefix = policy.get("generated_marker_prefix", "<!-- generated by")
    decision_indexes = {index_path_for(tree)
                        for tree in policy.get("decision_trees", {}).values()
                        if tree.get("render_index", True)}
    for view in policy.get("generated_views", []):
        path = vault.root / view
        if not path.is_file():
            if view in decision_indexes:
                owners = [t for t in policy["decision_trees"].values()
                          if index_path_for(t) == view]
                if not any(decision_notes(vault, t) for t in owners):
                    continue  # an index is born with its first decision
            findings.append(Finding(
                "error", view, 1, "generated_views",
                "policy-listed generated view is missing",
                "render it with its owning verb (render-decisions)"))
            continue
        first = path.read_text(encoding="utf-8",
                               errors="replace").splitlines()
        if not first or not first[0].startswith(marker_prefix):
            findings.append(Finding(
                "error", view, 1, "generated_views",
                "generated view lacks the first-line marker",
                "re-render it; a marker-less copy dodges the edit guard"))
    check_relation_projections(vault, findings)
    for rel, note in sorted(vault.notes.items()):
        if ("/_relations/" not in f"/{rel}"
                and "/_navigation/" not in f"/{rel}"):
            continue
        links = [target for (_line, embed, target, _anchor, _alias, _inner)
                 in note.wikilinks if not embed and target]
        if len(links) > 100:
            findings.append(Finding(
                "error", rel, 1, "generated_views",
                "generated navigation catalog exceeds 100 links",
                "re-render it; structural and relation catalogs shard at"
                " 100 links per page"))


def check_home_shape(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    maps_dir = policy["maps_dir"]
    home = vault.notes.get(policy["home_file"])
    if home is not None:
        targets = {t for (_l, _e, t, _a, _al, _inner) in home.wikilinks}
        for (lineno, _e, target, _a, _al, _inner) in home.wikilinks:
            if not target.startswith(f"{maps_dir}/"):
                findings.append(Finding(
                    "error", home.rel, lineno, "home_shape",
                    f"home links '{target}'; home links only map notes",
                    "the graph star topology depends on home -> maps ->"
                    " docs; move the link into the owning map"))
        if home.fm.get("type") != "home":
            findings.append(Finding(
                "error", home.rel, 1, "home_shape",
                "home note must carry type: home",
                "home and maps are navigation, typed as such"))
        # Dynamic home: every content-bearing subtree's map and the
        # extra maps are linked; empty-tree maps are not.
        required = [f"{maps_dir}/{name}"
                    for name in policy.get("extra_maps", [])]
        for subtree in policy["subtrees"]:
            if subtree_has_notes(vault, subtree):
                required.append(f"{maps_dir}/{subtree}")
            elif f"{maps_dir}/{subtree}" in targets:
                findings.append(Finding(
                    "error", home.rel, 1, "home_shape",
                    f"home links the empty tree's map"
                    f" '{maps_dir}/{subtree}'",
                    "home is dynamic: a map line joins when its tree"
                    " gains content, not before"))
        for target in required:
            if target not in targets:
                findings.append(Finding(
                    "error", home.rel, 1, "home_shape",
                    f"home does not link '{target}'",
                    "home links every content-bearing subtree map; the"
                    " birthing entry adds the line"))
    for rel, note in sorted(vault.notes.items()):
        if not rel.startswith(f"{maps_dir}/") or note.generated:
            continue
        if note.fm.get("type") != "moc":
            findings.append(Finding(
                "error", rel, 1, "home_shape",
                "map note must carry type: moc",
                "maps are navigation hubs, typed as such"))
        if "status" in note.fm:
            findings.append(Finding(
                "error", rel, 1, "home_shape",
                "map notes carry no status lifecycle",
                "navigation is never draft or approved; drop the key"))


def check_obsidian_payload(vault: Vault, findings: list[Finding],
                           payload_dir: Path | None,
                           require_local_projection: bool = False) -> None:
    policy = vault.policy
    for error in graph_type_coverage_errors(policy):
        findings.append(Finding(
            "error", "vault-policy.json", 1, "obsidian_payload", error,
            "assign every active document type to exactly one policy graph group"))
    obsidian = vault.root / ".obsidian"
    for name in PAYLOAD_FILES:
        if not (obsidian / name).is_file():
            findings.append(Finding(
                "error", f".obsidian/{name}", 1, "obsidian_payload",
                "tracked managed payload file is missing",
                "copy the vault payload (per-file, only where missing)"))
    brand_source = payload_dir / "snippets" / "brand.css" \
        if payload_dir is not None else None
    brand_target = obsidian / "snippets" / "brand.css"
    if (brand_source is not None and brand_source.is_file()
            and brand_target.is_file()
            and brand_target.read_bytes() != brand_source.read_bytes()):
        findings.append(Finding(
            "error", ".obsidian/snippets/brand.css", 1,
            "obsidian_payload",
            "brand.css does not match the installed package",
            "the house visual contract is package-owned; rerun project "
            "refresh while appearance.json remains project-owned",
        ))
    appearance_path = obsidian / "appearance.json"
    if appearance_path.is_file():
        try:
            appearance = json.loads(
                appearance_path.read_text(encoding="utf-8")
            )
        except json.JSONDecodeError:
            appearance = None
            findings.append(Finding(
                "error", ".obsidian/appearance.json", 1,
                "obsidian_payload", "appearance.json does not parse",
                "repair the project-owned appearance JSON and rerun setup",
            ))
        enabled = appearance.get("enabledCssSnippets") \
            if isinstance(appearance, dict) else None
        if isinstance(appearance, dict) and (
                not isinstance(enabled, list) or "brand" not in enabled):
            findings.append(Finding(
                "error", ".obsidian/appearance.json", 1,
                "obsidian_payload",
                "enabledCssSnippets must include brand",
                "brand enablement is managed while other appearance knobs "
                "and snippets remain project-owned",
            ))
    app_path = obsidian / "app.json"
    if app_path.is_file():
        try:
            app = json.loads(app_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            app = None
            findings.append(Finding(
                "error", ".obsidian/app.json", 1, "obsidian_payload",
                "app.json does not parse", "restore it from the payload"))
        if isinstance(app, dict):
            sentinels = dict(APP_SENTINELS)
            sentinels["attachmentFolderPath"] = policy.get(
                "attachments_dir", "_attachments")
            for key, expected in sentinels.items():
                if app.get(key) != expected:
                    findings.append(Finding(
                        "error", ".obsidian/app.json", 1, "obsidian_payload",
                        f"app.json {key} must be {json.dumps(expected)}",
                        "these keys control what the vault app writes;"
                        " drift makes the app author against the law"))
    core_path = obsidian / "core-plugins.json"
    if core_path.is_file():
        try:
            core = json.loads(core_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            core = None
            findings.append(Finding(
                "error", ".obsidian/core-plugins.json", 1, "obsidian_payload",
                "core-plugins.json does not parse",
                "restore it from the payload"))
        bases_on = (("bases" in core) if isinstance(core, list)
                    else bool(core.get("bases")) if isinstance(core, dict)
                    else False)
        if bases_on:
            findings.append(Finding(
                "error", ".obsidian/core-plugins.json", 1, "obsidian_payload",
                "the bases plugin is off in this vault generation",
                "views are markdown maps and generated indexes; disable it"))
    types_path = obsidian / "types.json"
    if types_path.is_file():
        try:
            types = json.loads(types_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            types = {}
            findings.append(Finding(
                "error", ".obsidian/types.json", 1, "obsidian_payload",
                "types.json does not parse", "restore it from the payload"))
        declared = types.get("types", {}) if isinstance(types, dict) else {}
        for key, expected in sorted(policy.get("property_types", {}).items()):
            if declared.get(key) != expected:
                findings.append(Finding(
                    "error", ".obsidian/types.json", 1, "obsidian_payload",
                    f"property '{key}' must be typed '{expected}'",
                    "types.json is derived from vault-policy.json"
                    " property_types; restore the drifted entry"))
        for key in policy.get("retired_managed_properties", []):
            if key in declared:
                findings.append(Finding(
                    "error", ".obsidian/types.json", 1, "obsidian_payload",
                    f"retired managed property '{key}' is still declared",
                    "project refresh removes package-owned property types"
                    " that no active document contract consumes"))
    graph_path = obsidian / "graph.json"
    expected_queries = graph_group_queries(policy)
    if graph_path.is_file() and expected_queries:
        try:
            graph = json.loads(graph_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            graph = None
            findings.append(Finding(
                "error", ".obsidian/graph.json", 1, "obsidian_payload",
                "graph.json does not parse", "restore it from the payload"))
        if isinstance(graph, dict):
            expected_groups = standard_graph_color_groups(policy)
            if graph.get("colorGroups") != expected_groups:
                findings.append(Finding(
                    "error", ".obsidian/graph.json", 1, "obsidian_payload",
                    "graph.json colorGroups do not match policy"
                    " graph_color_groups (same queries, RGB and order)",
                    "the type-based legend is policy data; run"
                    " standardize-graph-colors to restore it"))
            if graph.get("search", "") != policy.get("graph_search", ""):
                findings.append(Finding(
                    "error", ".obsidian/graph.json", 1, "obsidian_payload",
                    "graph.json search does not match policy graph_search",
                    "the global graph filter is policy data; rerun setup to"
                    " reconcile it"))
    community = policy.get("community_plugins", [])
    local_projection_present = (
        (obsidian / "community-plugins.json").exists()
        or any((obsidian / "plugins" / plugin_id).exists()
               for plugin_id in community)
    )
    if community and (require_local_projection or local_projection_present):
        cp_path = obsidian / "community-plugins.json"
        cp_data = None
        if not cp_path.is_file():
            findings.append(Finding(
                "error", ".obsidian/community-plugins.json", 1,
                "obsidian_payload",
                "package-projected local enable list is missing",
                "rerun project refresh to restore the local Obsidian"
                " community-plugin projection"))
        else:
            try:
                cp_data = json.loads(cp_path.read_text(encoding="utf-8"))
            except json.JSONDecodeError:
                findings.append(Finding(
                    "error", ".obsidian/community-plugins.json", 1,
                    "obsidian_payload",
                    "community-plugins.json does not parse",
                    "restore it from the payload"))
        if isinstance(cp_data, list) and sorted(cp_data) != sorted(community):
            findings.append(Finding(
                "error", ".obsidian/community-plugins.json", 1,
                "obsidian_payload",
                "enabled community plugins must be exactly the"
                " policy-vetted set",
                "the vetted set lives in vault-policy.json"
                " community_plugins; enable nothing else"))
        for plugin_id in community:
            plugin_dir = obsidian / "plugins" / plugin_id
            for fname in ("manifest.json", "main.js", "data.json"):
                if not (plugin_dir / fname).is_file():
                    findings.append(Finding(
                        "error", f".obsidian/plugins/{plugin_id}/{fname}",
                        1, "obsidian_payload",
                        "vendored plugin file is missing",
                        "rerun project refresh to restore the package-local"
                        " plugin projection"))
            manifest_path = plugin_dir / "manifest.json"
            if manifest_path.is_file():
                try:
                    manifest = json.loads(
                        manifest_path.read_text(encoding="utf-8"))
                except json.JSONDecodeError:
                    manifest = {}
                if isinstance(manifest, dict) \
                        and manifest.get("id") != plugin_id:
                    findings.append(Finding(
                        "error",
                        f".obsidian/plugins/{plugin_id}/manifest.json", 1,
                        "obsidian_payload",
                        f"manifest id '{manifest.get('id')}' does not match"
                        f" the plugin directory '{plugin_id}'",
                        "the enable list, the directory and the manifest"
                        " name one plugin"))
            if plugin_id == TITLE_PLUGIN_ID:
                check_title_plugin_data(plugin_dir / "data.json", findings)


def check_title_plugin_data(data_path: Path,
                            findings: list[Finding]) -> None:
    """The title plugin's settings contract, asserted key by key so a
    drifted key can never silently no-op."""
    rel = f".obsidian/plugins/{TITLE_PLUGIN_ID}/data.json"
    if not data_path.is_file():
        return  # the missing-file finding is already emitted
    try:
        data = json.loads(data_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        findings.append(Finding(
            "error", rel, 1, "obsidian_payload",
            "data.json does not parse", "restore it from the payload"))
        return
    common = (data.get("templates", {}) or {}).get("common", {}) \
        if isinstance(data, dict) else {}
    if not isinstance(common, dict) or common.get("main") != "title":
        findings.append(Finding(
            "error", rel, 1, "obsidian_payload",
            "templates.common.main must be the bare key 'title'",
            "the plugin reads a bare frontmatter key name here; any other"
            " form breaks every displayed label"))
    features = data.get("features", {}) if isinstance(data, dict) else {}
    for name in TITLE_PLUGIN_FEATURES_ON:
        spec = features.get(name) if isinstance(features, dict) else None
        if not (isinstance(spec, dict) and spec.get("enabled") is True):
            findings.append(Finding(
                "error", rel, 1, "obsidian_payload",
                f"features.{name}.enabled must be true",
                "titles replace filenames in every read surface; a"
                " disabled feature silently shows raw filenames"))
    for name in TITLE_PLUGIN_FEATURES_OFF:
        spec = features.get(name) if isinstance(features, dict) else None
        if not (isinstance(spec, dict) and spec.get("enabled") is False):
            findings.append(Finding(
                "error", rel, 1, "obsidian_payload",
                f"features.{name}.enabled must be false",
                "noteLink rewrites notes on disk past the write-time"
                " hooks and alias generation is pinned off for"
                " determinism"))


